import sys
import os
import random
import string

def generate_token():
    """Generate a random token using only letters and digits."""
    length = 16
    characters = string.ascii_letters + string.digits
    return ''.join(random.choice(characters) for _ in range(length))

def load_tokens():
    """Load tokens from the persistent store file."""
    file_path = "tokens.txt"
    tokens = []
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line:
                    token, user_id = line.split(' ', 1)
                    tokens.append((token, user_id))
    return tokens

def save_tokens(tokens):
    """Save tokens to the persistent store file in order."""
    file_path = "tokens.txt"
    with open(file_path, 'w') as file:
        for token, user_id in tokens:
            file.write(f"{token} {user_id}\n")

def issue(user_id):
    """Issue a new token for the given user_id."""
    tokens = load_tokens()
    token = generate_token()

    # Ensure the token is unique
    while any(t[0] == token for t in tokens):
        token = generate_token()

    # Add the new token to the list
    new_tokens = tokens + [(token, user_id)]
    save_tokens(new_tokens)

    print(token)

def validate(token):
    """Validate a token and print the result."""
    tokens = load_tokens()
    for t, user_id in tokens:
        if t == token:
            print(f"VALID {user_id}")
            return
    print("INVALID")

def list_tokens():
    """List all stored tokens in order of issuance."""
    tokens = load_tokens()
    for token, user_id in tokens:
        print(f"{token} {user_id}")

def main():
    if len(sys.argv) < 3:
        print("Usage: python token_manager.py <command> <args>")
        print("Commands: issue <user_id>, validate <token>, list")
        sys.exit(1)

    command = sys.argv[1]

    if command == "issue":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py issue <user_id>")
            sys.exit(1)
        issue(sys.argv[2])

    elif command == "validate":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py validate <token>")
            sys.exit(1)
        validate(sys.argv[2])

    elif command == "list":
        list_tokens()

    else:
        print("Unknown command. Use 'issue', 'validate', or 'list'.")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import requests
import csv

def main():
    # Read the path to the text file from standard input
    file_path = sys.stdin.readline().strip()

    if not file_path:
        print("Error: No file path provided.", file=sys.stderr)
        sys.exit(1)

    # Create a summary CSV file
    with open('summary.csv', 'w', newline='') as csvfile:
        fieldnames = ['url', 'status_code', 'content_length']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()

        # Open and read the input file
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                for line_num, line in enumerate(file, 1):
                    url = line.strip()
                    if not url:
                        continue

                    try:
                        response = requests.get(url, timeout=10)
                        writer.writerow({
                            'url': url,
                            'status_code': response.status_code,
                            'content_length': response.headers.get('content-length', '0')
                        })
                    except requests.RequestException:
                        writer.writerow({
                            'url': url,
                            'status_code': 0,
                            'content_length': 0
                        })
        except FileNotFoundError:
            print(f"Error: File '{file_path}' not found.", file=sys.stderr)
            sys.exit(1)
        except PermissionError:
            print(f"Error: Permission denied when reading '{file_path}'.", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import requests
import os
from typing import Dict, Any, List

def load_config(config_path: str) -> Dict[str, Any]:
    with open(config_path, 'r') as f:
        return json.load(f)

def fetch_metric(url: str) -> float:
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or "metric" not in data:
            raise ValueError("Invalid response format")
        return float(data["metric"])
    except Exception as e:
        raise RuntimeError(f"Failed to fetch metric from {url}: {str(e)}")

def save_cache(cache_file: str, name_to_metric: Dict[str, float], mean: float):
    cache_data = {
        "name_to_metric": name_to_metric,
        "mean": mean
    }
    with open(cache_file, 'wb') as f:
        f.write(json.dumps(cache_data).encode('utf-8'))

def load_cache(cache_file: str) -> Dict[str, Any]:
    if not os.path.exists(cache_file):
        return None
    with open(cache_file, 'rb') as f:
        data = f.read().decode('utf-8')
        return json.loads(data)
    return None

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_summary.py <config_file> [--offline]")
        sys.exit(1)

    config_path = sys.argv[1]
    offline_flag = '--offline' in sys.argv

    config = load_config(config_path)
    sources = config.get("sources", [])
    cache_file = config.get("cache_file", "./cache.bin")

    if offline_flag:
        cached_data = load_cache(cache_file)
        if cached_data is None:
            print("no cache available", file=sys.stderr)
            sys.exit(1)

        name_to_metric = cached_data["name_to_metric"]
        mean = cached_data["mean"]

        for source in sources:
            name = source["name"]
            if name in name_to_metric:
                print(f"{name}: {name_to_metric[name]}")
        print(f"mean: {mean}")
    else:
        name_to_metric = {}
        for source in sources:
            name = source["name"]
            url = source["url"]
            try:
                metric = fetch_metric(url)
                name_to_metric[name] = metric
            except Exception as e:
                print(f"Error fetching {url}: {str(e)}", file=sys.stderr)

        mean = sum(name_to_metric.values()) / len(name_to_metric) if name_to_metric else 0.0

        # Save to cache
        save_cache(cache_file, name_to_metric, mean)

        # Print results
        for source in sources:
            name = source["name"]
            print(f"{name}: {name_to_metric[name]}")
        print(f"mean: {mean}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    overrides = sys.argv[2:]

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML file: {e}")
    except FileNotFoundError:
        sys.exit(f"File not found: {xml_path}")

    # Build initial dictionary from XML entries
    config_dict = {}
    for entry in root:
        if entry.tag == 'entry':
            name = entry.get('name')
            value = entry.get('value')
            if name and value:
                config_dict[name] = value

    # Apply command-line overrides
    for override in overrides:
        if '=' in override:
            name, value = override.split('=', 1)
            config_dict[name] = value

    # Print the result as JSON
    print(json.dumps(config_dict, indent=2))

if __name__ == "__main__":
    main()

