import sys
import json
import os

def main():
    if len(sys.argv) != 2:
        print("ERROR: unknown operation")
        sys.exit(1)

    operation_name = sys.argv[1]

    # Read input from stdin
    try:
        input_line = sys.stdin.readline().strip()
        if not input_line:
            print("ERROR: invalid token")
            sys.exit(1)
        input_data = json.loads(input_line)
    except json.JSONDecodeError:
        print("ERROR: invalid token")
        sys.exit(1)

    # Read token from environment
    token_str = os.getenv("APP_TOKEN")
    if not token_str:
        print("ERROR: invalid token")
        sys.exit(1)

    try:
        token_data = json.loads(token_str)
    except json.JSONDecodeError:
        print("ERROR: invalid token")
        sys.exit(1)

    if "user" not in token_data or "roles" not in token_data:
        print("ERROR: invalid token")
        sys.exit(1)

    user = token_data["user"]
    roles = token_data["roles"]

    # Define operations
    OPERATIONS = [
        {
            "name": "sum",
            "required_role": "math",
            "expression": "x + y",
        },
        {
            "name": "greet",
            "required_role": "reports",
            "expression": "f'Hello, {user}! You sent {msg}.'",
        },
    ]

    # Find operation by name
    operation = next((op for op in OPERATIONS if op["name"] == operation_name), None)
    if not operation:
        print("ERROR: unknown operation")
        sys.exit(1)

    # Check role authorization
    if operation["required_role"] not in roles:
        print("ERROR: forbidden")
        sys.exit(1)

    # Evaluate expression with available variables
    try:
        # Create a safe namespace for evaluation
        namespace = input_data.copy()
        namespace["user"] = user
        result = eval(operation["expression"], {}, namespace)
    except Exception as e:
        print("ERROR: invalid operation")
        sys.exit(1)

    # Format and output result
    output = {
        "operation": operation_name,
        "user": user,
        "result": result
    }
    print(json.dumps(output))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import subprocess
import requests

def main():
    if len(sys.argv) != 2:
        print("Usage: python http_check_runner.py <path_to_xml_config>")
        sys.exit(1)

    xml_path = sys.argv[1]

    try:
        with open(xml_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        print(f"Error: XML file not found at {xml_path}")
        sys.exit(1)

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as e:
        print(f"Error: Invalid XML format - {e}")
        sys.exit(1)

    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        url = check_elem.get('url')

        if not name or not url:
            print("Error: Missing 'name' or 'url' attribute in <check> element")
            sys.exit(1)

        try:
            response = requests.get(url, timeout=10)
            status_code = response.status_code
            print(f"CHECK {name} {status_code}")

            on_fail_elem = check_elem.find('on_fail')
            if on_fail_elem is not None and status_code != 200:
                cmd = on_fail_elem.text.strip()
                if cmd:
                    try:
                        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
                        print(f"CMD {name} {result.returncode}")
                    except Exception as e:
                        print(f"CMD {name} 1")
        except requests.exceptions.RequestException as e:
            print(f"CHECK {name} 0")
            on_fail_elem = check_elem.find('on_fail')
            if on_fail_elem is not None:
                cmd = on_fail_elem.text.strip()
                if cmd:
                    try:
                        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
                        print(f"CMD {name} {result.returncode}")
                    except Exception as e:
                        print(f"CMD {name} 1")

if __name__ == "__main__":
    main()

import sys
import subprocess
import hashlib
import re

def evaluate_condition(condition_str, run_level):
    try:
        # Replace RUN_LEVEL with the actual value
        condition_with_run_level = condition_str.replace('RUN_LEVEL', str(run_level))
        # Evaluate the expression safely
        result = eval(condition_with_run_level)
        return result
    except Exception:
        return 0

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            for line in file:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue

                fields = line.split('\t')
                if len(fields) != 3:
                    continue

                command, condition, expected_digest = fields
                command = command.strip()
                condition = condition.strip()
                expected_digest = expected_digest.strip()

                run_level = int(os.getenv('RUN_LEVEL', '0'))

                condition_result = evaluate_condition(condition, run_level)

                if condition_result == 0:
                    print(f"SKIP\t{command}")
                else:
                    try:
                        # Run the command and capture output
                        result = subprocess.run(
                            command,
                            shell=True,
                            capture_output=True,
                            text=False,
                            timeout=30
                        )

                        if result.returncode != 0:
                            print(f"MISMATCH\t{command}")
                        else:
                            # Compute hash of the output bytes
                            output_bytes = result.stdout
                            hash_object = hashlib.sha256(output_bytes)
                            actual_digest = hash_object.hexdigest().lower()

                            if actual_digest == expected_digest:
                                print(f"OK\t{command}")
                            else:
                                print(f"MISMATCH\t{command}")

                    except subprocess.TimeoutExpired:
                        print(f"MISMATCH\t{command}")
                    except Exception as e:
                        print(f"MISMATCH\t{command}")

    except FileNotFoundError:
        sys.exit(1)
    except Exception as e:
        sys.exit(1)

if __name__ == "__main__":
    import os
    main()

import sys
import re
import xml.etree.ElementTree as ET

def parse_xml_config(xml_path):
    with open(xml_path, 'r', encoding='utf-8') as file:
        content = file.read()

    root = ET.fromstring(content)
    variables = {}
    for var in root.findall('variable'):
        name = var.get('name')
        value_str = var.get('value')
        if value_str is not None:
            try:
                value = float(value_str)
                variables[name] = value
            except ValueError:
                pass
    return variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names in the expression with their values
        for var_name, var_value in variables.items():
            expr = expr.replace(f'{{{{{{{var_name}}}}}}}}', str(var_value))

        # Evaluate the arithmetic expression
        result = eval(expr)
        return str(result)
    except Exception as e:
        return str(e)

def process_template(template_text, variables):
    # Find all {{EXPR}} placeholders
    pattern = r'\{\{([^{}]*)\}\}'
    def replace_match(match):
        expr = match.group(1)
        try:
            # Evaluate the expression using the variables
            result = evaluate_expression(expr, variables)
            return result
        except:
            return expr  # fallback if evaluation fails

    return re.sub(pattern, replace_match, template_text)

def main():
    print("Enter config XML path: ", end="")
    config_path = input().strip()

    print("Enter template path: ", end="")
    template_path = input().strip()

    print("Enter output path: ", end="")
    output_path = input().strip()

    # Parse XML configuration
    variables = parse_xml_config(config_path)

    # Read template file
    with open(template_path, 'r', encoding='utf-8') as file:
        template_content = file.read()

    # Process template with variables
    processed_content = process_template(template_content, variables)

    # Write result to output file
    with open(output_path, 'w', encoding='utf-8') as file:
        file.write(processed_content)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET

def main():
    if len(sys.argv) != 2:
        print("Usage: python allocator.py CONFIG_PATH")
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()

        max_total_bytes = int(root.find('maxTotalBytes').text)

    except ET.ParseError as e:
        print(f"Error parsing XML configuration: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Error reading configuration file: {e}")
        sys.exit(1)

    workload_path = input().strip()

    if not workload_path:
        print("Workload path is empty.")
        sys.exit(1)

    try:
        with open(workload_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue

                parts = line.split()
                if len(parts) != 3 or parts[0] != 'ALLOCATE':
                    print(f"Invalid instruction format: {line}")
                    continue

                user_id = parts[1]
                requested = int(parts[2])

                # Track current allocations per user
                allocations = {}
                total_allocated = 0

                # Check if allocation is possible
                if total_allocated + requested > max_total_bytes:
                    print(f"THROTTLED {user_id} {requested}")
                else:
                    # Accept allocation
                    if user_id in allocations:
                        allocations[user_id] += requested
                    else:
                        allocations[user_id] = requested
                    total_allocated += requested
                    print(f"ALLOCATED {user_id} {requested}")

    except FileNotFoundError:
        print(f"Workload file not found: {workload_path}")
        sys.exit(1)
    except Exception as e:
        print(f"Error processing workload file: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import json
import requests
from xml.etree import ElementTree as ET
from urllib.parse import urlparse

def parse_config(xml_path):
    try:
        with open(xml_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except FileNotFoundError:
        sys.exit(f"Configuration file {xml_path} not found.")

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML configuration: {e}")

    feeds = []
    for feed_elem in root.findall('feed'):
        url = feed_elem.get('url')
        name = feed_elem.get('name')
        if not url:
            sys.exit("Missing 'url' attribute in feed element.")
        if not name:
            name = url
        feeds.append({'url': url, 'name': name})
    return feeds

def fetch_feed_titles(feeds):
    result = {}
    for feed in feeds:
        url = feed['url']
        name = feed['name']
        try:
            response = requests.get(url, timeout=10)
            if response.status_code == 200 and response.content:
                try:
                    root = ET.fromstring(response.content)
                    titles = []
                    for item in root.findall('.//item'):
                        title_elem = item.find('title')
                        if title_elem is not None:
                            titles.append(title_elem.text if title_elem.text else "")
                    result[name] = titles
                except ET.ParseError:
                    result[name] = []
            else:
                result[name] = []
        except requests.RequestException:
            result[name] = []
    return result

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: python fetch_feed_titles.py path/to/config.xml")

    config_path = sys.argv[1]
    feeds = parse_config(config_path)
    titles_data = fetch_feed_titles(feeds)
    print(json.dumps(titles_data, indent=2))

if __name__ == "__main__":
    main()

import sys
import json
import os

def login_mode():
    line = sys.stdin.readline().strip()
    if not line:
        print(json.dumps({"error": "invalid_credentials"}))
        return

    try:
        data = json.loads(line)
        accounts = data.get("accounts", [])
        username = sys.stdin.readline().strip()
        password = sys.stdin.readline().strip()

        if not username or not password:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        matched = False
        for account in accounts:
            if account.get("username") == username and account.get("password") == password:
                matched = True
                break

        if not matched:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        # Generate a non-empty token
        token = "token_" + username + "_" + str(hash(username + password)) % 1000000
        result = {
            "username": username,
            "token": token
        }
        print(json.dumps(result))

    except Exception:
        print(json.dumps({"error": "invalid_credentials"}))

def page_mode():
    try:
        first_line = sys.stdin.readline().strip()
        second_line = sys.stdin.readline().strip()

        if not first_line or not second_line:
            print("NO ACCESS")
            return

        sessions_data = json.loads(first_line)
        token_data = json.loads(second_line)

        sessions = sessions_data.get("sessions", [])
        provided_token = token_data.get("token")

        if not provided_token:
            print("NO ACCESS")
            return

        matched = False
        for session in sessions:
            if session.get("token") == provided_token:
                matched = True
                username = session.get("username")
                token = provided_token
                break

        if not matched:
            print("NO ACCESS")
            return

        # Read profile_template.html
        template_path = "profile_template.html"
        if not os.path.exists(template_path):
            print("NO ACCESS")
            return

        with open(template_path, 'r') as f:
            template = f.read()

        # Replace placeholders
        html = template.replace("{{username}}", username).replace("{{token}}", token)
        print(html)

    except Exception:
        print("NO ACCESS")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)

    mode = sys.argv[1]
    if mode == "login":
        login_mode()
    elif mode == "page":
        page_mode()
    else:
        sys.exit(1)

import sys
import json
import xml.etree.ElementTree as ET
import os

def parse_config(config_path):
    tree = ET.parse(config_path)
    root = tree.getroot()
    calculations = {}
    for calc in root:
        name = calc.get('name')
        expr = calc.get('expr')
        if not name or not expr:
            raise ValueError("Missing 'name' or 'expr' attribute in calculation element")
        calculations[name] = expr
    return calculations

def evaluate_expression(expr, variables):
    try:
        # Replace variable references with their values
        for var, value in variables.items():
            expr = expr.replace(f"{var}", str(value))
        # Evaluate the expression using eval
        result = eval(expr)
        return float(result) if isinstance(result, (int, float)) else result
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {str(e)}")

def run_mode(config_path, input_json):
    # Parse configuration
    calculations = parse_config(config_path)

    # Read input JSON from stdin
    try:
        input_data = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON input: {str(e)}")

    # Evaluate each calculation
    results = {}
    for name, expr in calculations.items():
        try:
            result = evaluate_expression(expr, input_data)
            results[name] = result
        except Exception as e:
            raise ValueError(f"Error evaluating calculation '{name}': {str(e)}")

    # Output results to stdout
    print(json.dumps(results))

    # Create cache file with full state
    cache_path = "calcflow.cache"
    cache_data = {
        "variables": input_data,
        "calculations": results,
        "config": calculations
    }
    with open(cache_path, 'w') as f:
        json.dump(cache_data, f, indent=2)

    return results

def replay_mode(cache_path):
    # Read cache file
    if not os.path.exists(cache_path):
        raise FileNotFoundError(f"Cache file not found: {cache_path}")

    with open(cache_path, 'r') as f:
        cache_data = json.load(f)

    # Output results to stdout
    print(json.dumps(cache_data["calculations"]))

def main():
    if len(sys.argv) != 3:
        print("Usage: python calcflow.py run <CONFIG_PATH> or python calcflow.py replay <CACHE_PATH>", file=sys.stderr)
        sys.exit(1)

    mode = sys.argv[1]
    path = sys.argv[2]

    if mode == "run":
        run_mode(path, None)
    elif mode == "replay":
        replay_mode(path)
    else:
        print("Invalid mode. Use 'run' or 'replay'.", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import pickle
import os

def parse_resources(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    resources = {}
    for resource_elem in root.findall('resource'):
        name = resource_elem.get('name')
        max_concurrent = int(resource_elem.get('max_concurrent'))
        resources[name] = max_concurrent
    return resources

def load_state(state_path):
    if not os.path.exists(state_path) or os.path.getsize(state_path) == 0:
        return {name: {'running': [], 'queued': []} for name in resources}
    with open(state_path, 'rb') as f:
        return pickle.load(f)

def save_state(state, state_path):
    with open(state_path, 'wb') as f:
        pickle.dump(state, f)

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python scheduler.py resources.xml state.bin\n")
        sys.exit(1)

    xml_path = sys.argv[1]
    state_path = sys.argv[2]

    # Parse resources from XML
    try:
        resources = parse_resources(xml_path)
    except ET.ParseError as e:
        sys.stderr.write(f"Error parsing XML: {e}\n")
        sys.exit(1)

    # Load state from file
    state = load_state(state_path)

    # Process input lines from stdin
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            continue
        resource_name = parts[0]
        job_id = parts[1]

        # Validate resource name
        if resource_name not in resources:
            continue

        max_concurrent = resources[resource_name]
        running_count = len(state[resource_name]['running'])

        if running_count < max_concurrent:
            # Job starts
            state[resource_name]['running'].append(job_id)
            print(f"start {job_id} on {resource_name}")
        else:
            # Job queues
            state[resource_name]['queued'].append(job_id)
            print(f"queue {job_id} on {resource_name}")

    # Save updated state
    save_state(state, state_path)

if __name__ == "__main__":
    main()

