import sys
import xml.etree.ElementTree as ET
import hashlib

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except (IOError, OSError):
        print("CONFIG ERROR")
        return

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError:
        print("CONFIG ERROR")
        return

    if root.tag != 'config':
        print("CONFIG ERROR")
        return

    var_map = {}

    for var_elem in root.findall('var'):
        name = var_elem.get('name')
        value_str = var_elem.get('value')
        if not name or not value_str:
            print("CONFIG ERROR")
            return
        try:
            value = int(value_str)
        except ValueError:
            print("CONFIG ERROR")
            return
        var_map[name] = value

    secret_elem = root.find('secret')
    if secret_elem is not None:
        secret_text = secret_elem.get('text')
        if secret_text is None:
            print("CONFIG ERROR")
            return
        # Compute hash of secret text
        hash_obj = hashlib.sha256(secret_text.encode('utf-8'))
        hex_hash = hash_obj.hexdigest()
        try:
            secret_hash = int(hex_hash, 16)
        except ValueError:
            print("CONFIG ERROR")
            return
        var_map['secret_hash'] = secret_hash

    # Process input lines
    try:
        while True:
            line = input().strip()
            if not line:
                continue
            try:
                result = eval(line, {}, var_map)
                print(result)
            except Exception:
                print("ERROR")
    except EOFError:
        pass

