            name = var_elem.get('name')
            value = var_elem.get('value')
            if name and value:
                variables[name] = float(value)

    return per_user_max, variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names in the expression with their values
        # We use a simple substitution for now, but we need to handle expressions safely
        # We'll use eval with a restricted namespace
        safe_globals = {
            'abs': abs,
            'int': int,
            'float': float,
            'round': round,
            'pow': pow,
            'operator': operator,
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
            '/': operator.truediv,
            '**': operator.pow,
        }
        safe_globals.update(variables)

        # Parse the expression to ensure it's valid
        node = ast.parse(expr, mode='eval')

        # Evaluate the expression in a safe environment
        result = eval(compile(node, '<string>', 'eval'), safe_globals, safe_globals)

        return result
    except Exception as e:
        return None

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    per_user_max, variables = parse_xml_config(xml_path)

    user_eval_count = {}

    try:
        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue

            parts = line.split(':', 1)
            if len(parts) != 2:
                continue

            user_id = parts[0].strip()
            expression = parts[1].strip()

            if user_id == '':
                continue

            if user_id in user_eval_count and user_eval_count[user_id] >= per_user_max:
                print(f"THROTTLED {user_id}")
                continue

            result = evaluate_expression(expression, variables)
            if result is None:
                print(f"ERROR {user_id}")
            else:
                user_eval_count[user_id] = user_eval_count.get(user_id, 0) + 1
                print(f"{user_id}: {result}")

    except Exception as e:
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import secrets
import string

def generate_token():
    """Generate a cryptographically secure random token using only letters and digits."""
    length = 16
    characters = string.ascii_letters + string.digits
    return ''.join(secrets.choice(characters) for _ in range(length))

def load_tokens():
    """Load tokens from the persistent store file."""
    file_path = "tokens.txt"
    tokens = []
    if os.path.exists(file_path):
        with open(file_path, 'r') as file:
            for line in file:
                line = line.strip()
                if line:
                    token, user_id = line.split(' ', 1)
                    tokens.append((token, user_id))
    return tokens

def save_tokens(tokens):
    """Save tokens to the persistent store file in order."""
    file_path = "tokens.txt"
    with open(file_path, 'w') as file:
        for token, user_id in tokens:
            file.write(f"{token} {user_id}\n")

def issue(user_id):
    """Issue a new token for the given user_id."""
    tokens = load_tokens()
    token = generate_token()

    # Ensure the token is unique
    while any(t[0] == token for t in tokens):
        token = generate_token()

    # Add the new token to the list
    new_tokens = tokens + [(token, user_id)]
    save_tokens(new_tokens)

    print(token)

def validate(token):
    """Validate a token and print the result."""
    tokens = load_tokens()
    for t, user_id in tokens:
        if t == token:
            print(f"VALID {user_id}")
            return
    print("INVALID")

def list_tokens():
    """List all stored tokens in order of issuance."""
    tokens = load_tokens()
    for token, user_id in tokens:
        print(f"{token} {user_id}")

def main():
    if len(sys.argv) < 3:
        print("Usage: python token_manager.py <command> <args>")
        print("Commands: issue <user_id>, validate <token>, list")
        sys.exit(1)

    command = sys.argv[1]

    if command == "issue":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py issue <user_id>")
            sys.exit(1)
        issue(sys.argv[2])

    elif command == "validate":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py validate <token>")
            sys.exit(1)
        validate(sys.argv[2])

    elif command == "list":
        list_tokens()

    else:
        print("Unknown command. Use 'issue', 'validate', or 'list'.")
        sys.exit(1)

if __name__ == "__main__":
    main()

