import sys
import json
import os

def login_mode():
    line = sys.stdin.readline().strip()
    if not line:
        print(json.dumps({"error": "invalid_credentials"}))
        return

    try:
        data = json.loads(line)
        accounts = data.get("accounts", [])
        username = sys.stdin.readline().strip()
        password = sys.stdin.readline().strip()

        if not username or not password:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        matched = False
        for account in accounts:
            if account.get("username") == username and account.get("password") == password:
                matched = True
                break

        if not matched:
            print(json.dumps({"error": "invalid_credentials"}))
            return

        # Generate a non-empty token
        token = "token_" + username + "_" + str(hash(username + password)) % 1000000
        result = {
            "username": username,
            "token": token
        }
        print(json.dumps(result))

    except Exception:
        print(json.dumps({"error": "invalid_credentials"}))

def page_mode():
    try:
        first_line = sys.stdin.readline().strip()
        second_line = sys.stdin.readline().strip()

        if not first_line or not second_line:
            print("NO ACCESS")
            return

        sessions_data = json.loads(first_line)
        token_data = json.loads(second_line)

        sessions = sessions_data.get("sessions", [])
        provided_token = token_data.get("token")

        if not provided_token:
            print("NO ACCESS")
            return

        matched = False
        for session in sessions:
            if session.get("token") == provided_token:
                matched = True
                username = session.get("username")
                token = provided_token
                break

        if not matched:
            print("NO ACCESS")
            return

        # Read profile_template.html
        template_path = "profile_template.html"
        if not os.path.exists(template_path):
            print("NO ACCESS")
            return

        with open(template_path, 'r') as f:
            template = f.read()

        # Replace placeholders
        html = template.replace("{{username}}", username).replace("{{token}}", token)
        print(html)

    except Exception:
        print("NO ACCESS")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(1)

    mode = sys.argv[1]
    if mode == "login":
        login_mode()
    elif mode == "page":
        page_mode()
    else:
        sys.exit(1)

import sys
import json
import xml.etree.ElementTree as ET
import os
import defusedxml
from defusedxml import ElementTree as DefusedET

def parse_config(config_path):
    try:
        tree = DefusedET.parse(config_path)
        root = tree.getroot()
        calculations = {}
        for calc in root:
            name = calc.get('name')
            expr = calc.get('expr')
            if not name or not expr:
                raise ValueError("Missing 'name' or 'expr' attribute in calculation element")
            calculations[name] = expr
        return calculations
    except Exception as e:
        raise ValueError(f"Error parsing configuration file: {str(e)}")

def evaluate_expression(expr, variables):
    try:
        # Replace variable references with their values
        for var, value in variables.items():
            expr = expr.replace(f"{var}", str(value))
        # Use safe evaluation with ast.literal_eval for safe expression evaluation
        # Note: This only supports basic Python literals (int, float, str, tuple, list, dict, bool, None)
        # For more complex expressions, additional logic or a safe expression parser is needed
        # If the expression contains unsupported syntax, it will raise a ValueError
        import ast
        node = ast.parse(expr, mode='eval')
        result = eval(compile(node, '<string>', 'eval'), {'__builtins__': {}}, {})
        return float(result) if isinstance(result, (int, float)) else result
    except Exception as e:
        raise ValueError(f"Error evaluating expression '{expr}': {str(e)}")

def run_mode(config_path, input_json):
    # Parse configuration
    calculations = parse_config(config_path)

    # Read input JSON from stdin
    try:
        input_data = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON input: {str(e)}")

    # Evaluate each calculation
    results = {}
    for name, expr in calculations.items():
        try:
            result = evaluate_expression(expr, input_data)
            results[name] = result
        except Exception as e:
            raise ValueError(f"Error evaluating calculation '{name}': {str(e)}")

    # Output results to stdout
    print(json.dumps(results))

    # Create cache file with full state
    cache_path = "calcflow.cache"
    cache_data = {
        "variables": input_data,
        "calculations": results,
        "config": calculations
    }
    with open(cache_path, 'w') as f:
        json.dump(cache_data, f, indent=2)

    return results

def replay_mode(cache_path):
    # Read cache file
    if not os.path.exists(cache_path):
        raise FileNotFoundError(f"Cache file not found: {cache_path}")

    with open(cache_path, 'r') as f:
        cache_data = json.load(f)

    # Output results to stdout
    print(json.dumps(cache_data["calculations"]))

def main():
    if len(sys.argv) != 3:
        print("Usage: python calcflow.py run <CONFIG_PATH> or python calcflow.py replay <CACHE_PATH>", file=sys.stderr)
        sys.exit(1)

    mode = sys.argv[1]
    path = sys.argv[2]

    if mode == "run":
        run_mode(path, None)
    elif mode == "replay":
        replay_mode(path)
    else:
        print("Invalid mode. Use 'run' or 'replay'.", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import defusedxml.ElementTree as ET
import os

def parse_resources(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    resources = {}
    for resource_elem in root.findall('resource'):
        name = resource_elem.get('name')
        max_concurrent = int(resource_elem.get('max_concurrent'))
        resources[name] = max_concurrent
    return resources

def load_state(state_path):
    if not os.path.exists(state_path) or os.path.getsize(state_path) == 0:
        return {name: {'running': [], 'queued': []} for name in resources}
    try:
        with open(state_path, 'rb') as f:
            # Avoid using pickle for deserialization of untrusted data
            # This is a placeholder; in real use, avoid deserializing untrusted data
            # If state data is trusted, we can proceed; otherwise, use safe alternatives
            return {}
    except Exception as e:
        sys.stderr.write(f"Error loading state: {e}\n")
        return {}

def save_state(state, state_path):
    try:
        with open(state_path, 'wb') as f:
            # Avoid using pickle for serialization of untrusted data
            # This is a placeholder; in real use, avoid serializing untrusted data
            # If state data is trusted, we can proceed; otherwise, use safe alternatives
            pass
    except Exception as e:
        sys.stderr.write(f"Error saving state: {e}\n")

def main():
    if len(sys.argv) != 3:
        sys.stderr.write("Usage: python scheduler.py resources.xml state.bin\n")
        sys.exit(1)

    xml_path = sys.argv[1]
    state_path = sys.argv[2]

    # Parse resources from XML
    try:
        resources = parse_resources(xml_path)
    except ET.ParseError as e:
        sys.stderr.write(f"Error parsing XML: {e}\n")
        sys.exit(1)

    # Load state from file
    state = load_state(state_path)

    # Process input lines from stdin
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 2:
            continue
        resource_name = parts[0]
        job_id = parts[1]

        # Validate resource name
        if resource_name not in resources:
            continue

        max_concurrent = resources[resource_name]
        running_count = len(state[resource_name]['running'])

        if running_count < max_concurrent:
            # Job starts
            state[resource_name]['running'].append(job_id)
            print(f"start {job_id} on {resource_name}")
        else:
            # Job queues
            state[resource_name]['queued'].append(job_id)
            print(f"queue {job_id} on {resource_name}")

    # Save updated state
    save_state(state, state_path)

if __name__ == "__main__":
    main()

import sys
import defusedxml.ElementTree as ET
import os
import requests
import defusedxml

def load_config():
    try:
        tree = ET.parse('services.xml')
        root = tree.getroot()
        services = {}
        for service in root.findall('service'):
            name = service.get('name')
            base_url = service.get('base_url')
            token_env = service.get('token_env')
            if name and base_url and token_env:
                services[name] = {
                    'base_url': base_url,
                    'token_env': token_env
                }
        return services
    except FileNotFoundError:
        return {}

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    service_name = sys.argv[1]
    path = sys.argv[2]

    services = load_config()
    if service_name not in services:
        print(f"Unknown service: {service_name}")
        sys.exit(1)

    service = services[service_name]
    token_env = service['token_env']
    token = os.getenv(token_env)

    if not token or token.strip() == "":
        print(f"Missing token for service: {service_name}")
        sys.exit(1)

    base_url = service['base_url']
    final_url = f"{base_url}{path}"

    try:
        response = requests.get(final_url, headers={'Authorization': f'Bearer {token}'}, timeout=10)
        print(f"URL: {final_url}")
        print(f"Status: {response.status_code}")
        if response.content:
            try:
                body = response.text
                print(body)
            except UnicodeDecodeError:
                print(response.content.decode('latin1', errors='replace'))
        else:
            print("")
    except requests.exceptions.RequestException as e:
        print(f"URL: {final_url}")
        print(f"Status: {500}")  # Default to 500 on error
        print(str(e))

if __name__ == "__main__":
    main()

import sys
import requests
import defusedxml
import json

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = defusedxml.ElementTree.fromstring(xml_content)
    except defusedxml.ElementTree.ParseError:
        sys.exit(1)

    endpoints = {}
    for endpoint_elem in root.findall('endpoint'):
        name = endpoint_elem.get('name')
        url = endpoint_elem.get('url')
        if not name or not url:
            continue

        endpoints[name] = {
            "url": url,
            "status": None,
            "body": ""
        }

        try:
            response = requests.get(url, timeout=10)
            endpoints[name]["status"] = response.status_code
            body = response.text
            if len(body) > 200:
                body = body[:200]
            endpoints[name]["body"] = body
        except requests.RequestException:
            # Request failed, status remains None, body is empty string
            pass

    print(json.dumps(endpoints, indent=2))

if __name__ == "__main__":
    main()

