import sys
import defusedxml.ElementTree as ET
import hashlib

def compute_digest(secret_key, token):
    """Compute a deterministic digest from secret key and token."""
    return hashlib.md5((secret_key + token).encode()).hexdigest()

def main():
    if len(sys.argv) != 4:
        sys.exit(1)

    config_path = sys.argv[1]
    username = sys.argv[2]
    action = sys.argv[3]

    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            xml_content = f.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError:
        sys.exit(1)

    # Extract secret key
    secret_element = root.find('secret')
    if secret_element is None or secret_element.get('key') is None:
        sys.exit(1)

    secret_key = secret_element.get('key')

    # Find user by name
    user_element = root.find(f'.//user[@name="{username}"]')
    if user_element is None:
        print("DENIED")
        sys.exit(0)

    token_digest = user_element.get('tokenDigest')
    if token_digest is None:
        print("DENIED")
        sys.exit(0)

    # Read token from stdin
    try:
        token_input = input().strip()
    except EOFError:
        print("DENIED")
        sys.exit(0)

    # Compute digest and compare
    computed_digest = compute_digest(secret_key, token_input)
    if computed_digest != token_digest:
        print("DENIED")
        sys.exit(0)

    # Check action based on roles
    roles = user_element.get('roles', '').split(',')
    role_to_actions = {
        'reader': ['read'],
        'writer': ['read', 'write'],
        'admin': ['read', 'write', 'delete']
    }

    allowed_actions = set()
    for role in roles:
        if role in role_to_actions:
            allowed_actions.update(role_to_actions[role])

    if action in allowed_actions:
        print("ALLOWED")
    else:
        print("DENIED")

if __name__ == "__main__":
    main()

import sys
import json
import defusedxml
from defusedxml import ElementTree as ET
from typing import Dict, Any, Optional

def evaluate_condition(condition: str, env: Dict[str, Any]) -> bool:
    try:
        # Replace variables in condition with their values
        # Use safe evaluation with only allowed variables
        # Avoid eval with dangerous built-ins
        safe_env = env.copy()
        # Use literal_eval for safe evaluation of expressions
        # Only allow simple literals and variables from env
        import ast
        node = ast.parse(condition, mode='eval')
        for node in ast.walk(node):
            if isinstance(node, ast.Name):
                if node.id not in safe_env:
                    raise ValueError(f"Unknown variable: {node.id}")
        return eval(compile(node, '<string>', 'eval'), {"__builtins__": {}}, safe_env)
    except Exception:
        return False

def parse_request(input_line: str) -> Dict[str, Any]:
    try:
        return json.loads(input_line)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON input")

def main():
    if len(sys.argv) != 2:
        print("DENIED")
        sys.exit(1)

    xml_file_path = sys.argv[1]

    try:
        with open(xml_file_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        print("DENIED")
        sys.exit(1)

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError:
        print("DENIED")
        sys.exit(1)

    # Read request from stdin
    try:
        request_line = sys.stdin.readline().strip()
        if not request_line:
            print("DENIED")
            sys.exit(1)
        request = parse_request(request_line)
    except Exception:
        print("DENIED")
        sys.exit(1)

    # Extract request values
    user = request["user"]
    token = request["token"]
    action = request["action"]
    params = request["params"]

    # Build environment for condition evaluation
    env = {
        "user": user,
        "token": token,
        "action": action,
        "params": params
    }

    # Process each policy in order
    for policy_elem in root:
        if policy_elem.tag != "policy":
            continue

        policy_id = policy_elem.get("id")
        token_prefix = policy_elem.get("token_prefix")
        condition_str = policy_elem.get("condition")

        if not condition_str:
            continue

        # Check if token starts with token_prefix
        if not token.startswith(token_prefix):
            continue

        # Evaluate condition
        if evaluate_condition(condition_str, env):
            print(f"ALLOWED {policy_id}")
            return

    print("DENIED")

if __name__ == "__main__":
    main()

import sys
import defusedxml.ElementTree as ET
import hashlib
import ast

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except (IOError, OSError):
        print("CONFIG ERROR")
        return

    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError:
        print("CONFIG ERROR")
        return

    if root.tag != 'config':
        print("CONFIG ERROR")
        return

    var_map = {}

    for var_elem in root.findall('var'):
        name = var_elem.get('name')
        value_str = var_elem.get('value')
        if not name or not value_str:
            print("CONFIG ERROR")
            return
        try:
            value = int(value_str)
        except ValueError:
            print("CONFIG ERROR")
            return
        var_map[name] = value

    secret_elem = root.find('secret')
    if secret_elem is not None:
        secret_text = secret_elem.get('text')
        if secret_text is None:
            print("CONFIG ERROR")
            return
        # Compute hash of secret text
        hash_obj = hashlib.sha256(secret_text.encode('utf-8'))
        hex_hash = hash_obj.hexdigest()
        try:
            secret_hash = int(hex_hash, 16)
        except ValueError:
            print("CONFIG ERROR")
            return
        var_map['secret_hash'] = secret_hash

    # Process input lines
    try:
        while True:
            line = input().strip()
            if not line:
                continue
            try:
                # Use ast.literal_eval instead of eval for safe evaluation
                result = ast.literal_eval(line)
                if isinstance(result, (int, float, str, bool, type(None))):
                    print(result)
                else:
                    print("ERROR")
            except (ValueError, SyntaxError):
                print("ERROR")
    except EOFError:
        pass

if __name__ == "__main__":
    main()

import sys
import defusedxml.ElementTree as ET
from collections import defaultdict

def parse_config(config_path):
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = ET.fromstring(content)
        window_seconds = int(root.get('window_seconds'))
        clients = {}

        for client_elem in root.findall('client'):
            client_id = client_elem.get('id')
            max_active = int(client_elem.get('max_active'))
            max_new = int(client_elem.get('max_new'))
            tag = client_elem.get('tag')

            if not client_id or not tag:
                raise ValueError("Missing required client attributes")

            clients[client_id] = {
                'max_active': max_active,
                'max_new': max_new,
                'tag': tag
            }

        return window_seconds, clients
    except ET.ParseError as e:
        sys.exit(1)
    except ValueError as e:
        sys.exit(1)

def compute_signature(s):
    v = 0
    for c in s:
        u = ord(c)
        v = (v * 131 + u) % (2**64)
    return f"{v:016x}".lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: alloc_throttle.py CONFIG.xml")
        sys.exit(1)

    config_path = sys.argv[1]
    window_seconds, clients = parse_config(config_path)

    # Initialize state for each client
    active_count = defaultdict(int)
    allocation_history = defaultdict(list)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 3:
            continue

        client_id, timestamp_str, action = parts
        timestamp = int(timestamp_str)

        # Check if client exists in config
        if client_id not in clients:
            print(f"UNKNOWN {client_id}")
            continue

        # Remove timestamps older than window_seconds ago
        current_time = timestamp
        window_bound = current_time - window_seconds
        new_history = [t for t in allocation_history[client_id] if t >= window_bound]
        allocation_history[client_id] = new_history
        history_size = len(new_history)

        if action == "ALLOCATE":
            config = clients[client_id]
            active_count[client_id] += 1
            if active_count[client_id] > config['max_active']:
                active_count[client_id] -= 1
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            if history_size + 1 > config['max_new']:
                active_count[client_id] -= 1
                print(f"THROTTLED {client_id} {timestamp}")
                continue

            allocation_history[client_id].append(timestamp)
            signature = compute_signature(f"{client_id}|{timestamp}|ALLOCATE|{config['tag']}")
            print(f"ALLOCATED {client_id} {timestamp} {signature}")

        elif action == "RELEASE":
            if active_count[client_id] > 0:
                active_count[client_id] -= 1
                signature = compute_signature(f"{client_id}|{timestamp}|RELEASE|{clients[client_id]['tag']}")
                print(f"RELEASED {client_id} {timestamp} {signature}")
            else:
                print(f"IGNORED {client_id} {timestamp}")

if __name__ == "__main__":
    main()

import sys
import os
import subprocess
import json
import hashlib

def main():
    if len(sys.argv) != 2:
        print("Usage: python taskrunner.py PROJECT_FILE")
        sys.exit(1)

    project_file = sys.argv[1]

    if not os.path.exists(project_file):
        print("Project file not found.")
        sys.exit(1)

    # Define cache file
    cache_file = "task_cache.bin"

    # Load cache from file if it exists
    cache = {}
    if os.path.exists(cache_file):
        try:
            with open(cache_file, "rb") as f:
                # Read file content and verify integrity
                file_content = f.read()
                if not file_content:
                    cache = {}
                else:
                    # Hash the file content to verify integrity
                    file_hash = hashlib.sha256(file_content).hexdigest()
                    # We'll store the hash in a separate structure to verify later
                    # For now, just load the data and verify it's valid
                    try:
                        cache_data = json.loads(file_content.decode('utf-8'))
                        # Validate that cache_data is a dictionary with string keys and integer values
                        if isinstance(cache_data, dict):
                            for key, value in cache_data.items():
                                if not isinstance(key, str) or not isinstance(value, int):
                                    raise ValueError("Invalid cache data format")
                            cache = cache_data
                    except (json.JSONDecodeError, ValueError) as e:
                        print("Invalid cache file format or data. Starting with empty cache.")
                        cache = {}
        except (OSError, IOError) as e:
            print("Error reading cache file. Starting with empty cache.")
            cache = {}

    # Read and process project file
    with open(project_file, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue

            try:
                # Split by colon, ensuring only one split
                parts = line.split(":", 1)
                if len(parts) != 2:
                    continue

                task_name = parts[0].strip()
                command_text = parts[1].strip()

                # Validate task name: no colons, and no path traversal or malicious patterns
                if ":" in task_name or ".." in task_name or "/" in task_name or "\\" in task_name:
                    print(f"Invalid task name: {task_name}")
                    continue

                # Validate command text: avoid shell injection by not using shell=True
                # Instead, we will use a safe command execution method
                # We will only allow commands that are safe (no shell injection)
                # We will not execute commands with semicolons, pipes, or other shell metacharacters
                if ";" in command_text or "|" in command_text or "&" in command_text or "$" in command_text or "`" in command_text:
                    print(f"Invalid command text: {command_text}")
                    exit_code = 1
                else:
                    # Execute command safely using a list of arguments
                    try:
                        # Split command into arguments to avoid shell injection
                        # This is safe because we don't use shell=True
                        # We assume command_text is a simple command with no shell metacharacters
                        args = command_text.split()
                        if not args:
                            exit_code = 1
                        else:
                            result = subprocess.run(args, capture_output=True, text=True, timeout=30)
                            exit_code = result.returncode
                    except subprocess.TimeoutExpired:
                        exit_code = 1
                    except Exception as e:
                        exit_code = 1

                # Get previous exit code from cache
                prev_exit_code = cache.get(task_name)

                # Print output
                print(f"{task_name} EXIT={exit_code} PREV={prev_exit_code if prev_exit_code is not None else 'none'}")

                # Update cache
                cache[task_name] = exit_code

            except Exception as e:
                # Log error but do not crash
                print(f"Error processing task: {task_name} - {str(e)}")
                exit_code = 1
                prev_exit_code = cache.get(task_name)
                print(f"{task_name} EXIT={exit_code} PREV={prev_exit_code if prev_exit_code is not None else 'none'}")
                cache[task_name] = exit_code

    # Save updated cache to file with integrity verification
    try:
        # Serialize cache to JSON (safe format)
        cache_data = {}
        for key, value in cache.items():
            cache_data[key] = value

        # Create a hash of the data for integrity
        data_json = json.dumps(cache_data, sort_keys=True)
        data_hash = hashlib.sha256(data_json.encode('utf-8')).hexdigest()

        # Write to file with integrity check
        with open(cache_file, "wb") as f:
            f.write(data_json.encode('utf-8'))
            f.write(b"\n")
            f.write(data_hash.encode('utf-8'))

    except (OSError, IOError) as e:
        print("Error saving cache file.")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import secrets
import hashlib

def generate_token():
    """Generate a cryptographically secure token using only letters and digits."""
    # Use secrets to ensure randomness and avoid predictability
    length = 32
    characters = string.ascii_letters + string.digits
    token = ''.join(secrets.choice(characters) for _ in range(length))
    return token

def load_tokens():
    """Load tokens from the persistent store file with proper validation."""
    file_path = os.path.join(os.getcwd(), "tokens.txt")
    tokens = []
    if os.path.exists(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                for line in file:
                    line = line.strip()
                    if line and ' ' in line:
                        parts = line.split(' ', 1)
                        token, user_id = parts[0], parts[1]
                        # Validate that token and user_id are non-empty and contain only allowed characters
                        if token and user_id and all(c.isalnum() for c in token) and all(c.isalnum() for c in user_id):
                            tokens.append((token, user_id))
        except (IOError, OSError) as e:
            print(f"Error reading token file: {e}", file=sys.stderr)
    return tokens

def save_tokens(tokens):
    """Save tokens to the persistent store file in order with atomic write."""
    file_path = os.path.join(os.getcwd(), "tokens.txt")
    # Ensure the file is written with proper permissions
    try:
        # Create a temporary file to avoid race conditions
        temp_path = file_path + ".tmp"
        with open(temp_path, 'w', encoding='utf-8') as temp_file:
            for token, user_id in tokens:
                temp_file.write(f"{token} {user_id}\n")

        # Replace the original file with the temporary one
        os.replace(temp_path, file_path)
    except (IOError, OSError) as e:
        print(f"Error writing token file: {e}", file=sys.stderr)
        # Attempt to clean up if the temp file was created
        if os.path.exists(temp_path):
            os.remove(temp_path)
        sys.exit(1)

def issue(user_id):
    """Issue a new token for the given user_id with input validation."""
    # Validate user_id input
    if not user_id or not user_id.strip():
        print("Invalid user_id")
        sys.exit(1)

    # Validate that user_id contains only alphanumeric characters
    if not all(c.isalnum() for c in user_id):
        print("Invalid user_id: must contain only alphanumeric characters")
        sys.exit(1)

    tokens = load_tokens()
    token = generate_token()

    # Ensure the token is unique
    while any(t[0] == token for t in tokens):
        token = generate_token()

    # Add the new token to the list
    new_tokens = tokens + [(token, user_id)]
    save_tokens(new_tokens)

    print(token)

def validate(token):
    """Validate a token and print the result with input validation."""
    # Validate token input
    if not token or not token.strip():
        print("INVALID")
        return

    # Validate that token contains only alphanumeric characters
    if not all(c.isalnum() for c in token):
        print("INVALID")
        return

    tokens = load_tokens()
    for t, user_id in tokens:
        if t == token:
            print(f"VALID {user_id}")
            return
    print("INVALID")

def list_tokens():
    """List all stored tokens in order of issuance with validation."""
    tokens = load_tokens()
    for token, user_id in tokens:
        print(f"{token} {user_id}")

def main():
    if len(sys.argv) < 3:
        print("Usage: python token_manager.py <command> <args>")
        print("Commands: issue <user_id>, validate <token>, list")
        sys.exit(1)

    command = sys.argv[1]

    if command == "issue":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py issue <user_id>")
            sys.exit(1)
        issue(sys.argv[2])

    elif command == "validate":
        if len(sys.argv) != 3:
            print("Usage: python token_manager.py validate <token>")
            sys.exit(1)
        validate(sys.argv[2])

    elif command == "list":
        list_tokens()

    else:
        print("Unknown command. Use 'issue', 'validate', or 'list'.")
        sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import requests
import csv
from urllib.parse import urlparse
import os

def is_valid_url(url):
    """Validate URL to prevent open redirects, SSRF, and malformed URLs."""
    try:
        result = urlparse(url)
        return all([result.scheme in ['http', 'https'], result.netloc])
    except Exception:
        return False

def sanitize_path(path):
    """Sanitize file path to prevent directory traversal attacks."""
    # Normalize path and remove any path traversal components
    path = os.path.normpath(path)
    # Ensure the path is absolute and doesn't contain relative path components
    if not path.startswith('/'):
        path = '/' + path
    # Remove any path components that are dangerous
    dangerous_parts = ['..', '.']
    for part in dangerous_parts:
        if part in path:
            return None
    # Ensure the path is within a safe directory (e.g., current directory only)
    if '..' in path or os.path.isabs(path) and not path.startswith('/'):
        return None
    return path

def main():
    # Read the path to the text file from standard input
    file_path_input = sys.stdin.readline().strip()

    if not file_path_input:
        print("Error: No file path provided.", file=sys.stderr)
        sys.exit(1)

    # Sanitize the file path to prevent path traversal
    sanitized_path = sanitize_path(file_path_input)
    if not sanitized_path:
        print("Error: Invalid or dangerous file path provided.", file=sys.stderr)
        sys.exit(1)

    # Verify the sanitized path is within the expected directory
    if not os.path.exists(sanitized_path):
        print(f"Error: File '{sanitized_path}' not found.", file=sys.stderr)
        sys.exit(1)

    # Create a summary CSV file
    with open('summary.csv', 'w', newline='') as csvfile:
        fieldnames = ['url', 'status_code', 'content_length']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()

        # Open and read the input file
        try:
            with open(sanitized_path, 'r', encoding='utf-8') as file:
                for line_num, line in enumerate(file, 1):
                    url = line.strip()
                    if not url:
                        continue

                    # Validate the URL to prevent open redirects and SSRF
                    if not is_valid_url(url):
                        writer.writerow({
                            'url': url,
                            'status_code': 0,
                            'content_length': 0
                        })
                        continue

                    try:
                        response = requests.get(url, timeout=10)
                        content_length = response.headers.get('content-length', '0')
                        # Ensure content_length is a number
                        try:
                            content_length = int(content_length)
                        except (ValueError, TypeError):
                            content_length = 0

                        writer.writerow({
                            'url': url,
                            'status_code': response.status_code,
                            'content_length': content_length
                        })
                    except requests.RequestException:
                        writer.writerow({
                            'url': url,
                            'status_code': 0,
                            'content_length': 0
                        })
        except PermissionError:
            print(f"Error: Permission denied when reading '{sanitized_path}'.", file=sys.stderr)
            sys.exit(1)

if __name__ == "__main__":
    main()

import json
import sys
import requests
import os
from typing import Dict, Any, List
from pathlib import Path

def validate_url(url: str) -> bool:
    """Validate URL to prevent open redirects, path traversal, and SSRF."""
    if not url.startswith(('http://', 'https://')):
        return False
    # Allow only basic domain and path, disallow relative paths or traversal
    if '..' in url or '/./' in url or '/../' in url:
        return False
    # Limit path length to prevent excessive requests
    if len(url) > 2048:
        return False
    return True

def validate_config(config: Dict[str, Any]) -> bool:
    """Validate configuration structure and content."""
    if not isinstance(config, dict):
        return False
    if "sources" not in config or not isinstance(config["sources"], list):
        return False
    if "cache_file" not in config or not isinstance(config["cache_file"], str):
        return False

    for source in config["sources"]:
        if not isinstance(source, dict):
            return False
        if "name" not in source or "url" not in source:
            return False
        if not isinstance(source["name"], str) or not isinstance(source["url"], str):
            return False
        if len(source["name"]) == 0 or len(source["url"]) == 0:
            return False
    return True

def sanitize_name(name: str) -> str:
    """Sanitize name to prevent injection attacks."""
    if not isinstance(name, str):
        return ""
    # Remove any characters that could be used for injection
    sanitized = name.strip()
    # Prevent use of dangerous names
    if any(part in sanitized for part in ("__import__", "__dict__", "__class__", "system", "os", "eval", "exec")):
        return ""
    return sanitized

def fetch_metric(url: str) -> float:
    """Fetch metric from remote URL with validation."""
    if not validate_url(url):
        raise ValueError(f"Invalid or unsafe URL: {url}")
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()
        if not isinstance(data, dict) or "metric" not in data:
            raise ValueError("Invalid response format")
        metric_value = data["metric"]
        if not isinstance(metric_value, (int, float)):
            raise ValueError("Metric must be a number")
        return float(metric_value)
    except Exception as e:
        raise RuntimeError(f"Failed to fetch metric from {url}: {str(e)}")

def save_cache(cache_file: str, name_to_metric: Dict[str, float], mean: float):
    """Save cache data securely with integrity checks."""
    cache_data = {
        "name_to_metric": name_to_metric,
        "mean": mean
    }
    cache_path = Path(cache_file)
    # Ensure directory exists
    cache_path.parent.mkdir(parents=True, exist_ok=True)
    # Write in a way that prevents overwriting by other processes
    # Use a temporary file and rename after write
    temp_file = cache_path.with_suffix(cache_path.suffix + ".tmp")
    try:
        with open(temp_file, 'wb') as f:
            # Use a secure serialization format (JSON) with strict schema
            json_data = json.dumps(cache_data, separators=(',', ':'), ensure_ascii=True)
            f.write(json_data.encode('utf-8'))
        # Replace original file atomically
        temp_file.rename(cache_path)
    except Exception as e:
        # Clean up temp file if creation fails
        if temp_file.exists():
            temp_file.unlink()
        raise RuntimeError(f"Failed to save cache: {str(e)}")

def load_cache(cache_file: str) -> Dict[str, Any]:
    """Load cache data with strict validation and integrity checks."""
    cache_path = Path(cache_file)
    if not cache_path.exists():
        return None

    # Validate file integrity: check if it's a valid JSON file
    try:
        with open(cache_path, 'rb') as f:
            data = f.read()
            if not data:
                return None
            # Validate JSON structure
            json_data = data.decode('utf-8')
            parsed = json.loads(json_data)
            # Validate schema
            if not isinstance(parsed, dict):
                return None
            if "name_to_metric" not in parsed or "mean" not in parsed:
                return None
            if not isinstance(parsed["name_to_metric"], dict):
                return None
            if not isinstance(parsed["mean"], (int, float)):
                return None
            return parsed
    except Exception as e:
        # Log error but return None to indicate failure
        return None

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_summary.py <config_file> [--offline]")
        sys.exit(1)

    config_path = sys.argv[1]
    offline_flag = '--offline' in sys.argv

    # Validate command-line argument
    if not Path(config_path).is_absolute():
        config_path = os.path.abspath(config_path)

    # Load and validate configuration
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading configuration file: {str(e)}", file=sys.stderr)
        sys.exit(1)

    if not validate_config(config):
        print("Invalid configuration file structure", file=sys.stderr)
        sys.exit(1)

    sources = config.get("sources", [])
    cache_file = config.get("cache_file", "./cache.bin")

    if offline_flag:
        cached_data = load_cache(cache_file)
        if cached_data is None:
            print("no cache available", file=sys.stderr)
            sys.exit(1)

        name_to_metric = cached_data["name_to_metric"]
        mean = cached_data["mean"]

        for source in sources:
            name = source["name"]
            sanitized_name = sanitize_name(name)
            if sanitized_name and sanitized_name in name_to_metric:
                print(f"{sanitized_name}: {name_to_metric[sanitized_name]}")
        print(f"mean: {mean}")
    else:
        name_to_metric = {}
        for source in sources:
            name = source["name"]
            url = source["url"]
            sanitized_name = sanitize_name(name)
            if not sanitized_name:
                print(f"Invalid source name: {name}", file=sys.stderr)
                continue
            try:
                metric = fetch_metric(url)
                name_to_metric[sanitized_name] = metric
            except Exception as e:
                print(f"Error fetching {url}: {str(e)}", file=sys.stderr)

        mean = sum(name_to_metric.values()) / len(name_to_metric) if name_to_metric else 0.0

        # Save to cache with integrity and atomicity
        save_cache(cache_file, name_to_metric, mean)

        # Print results
        for source in sources:
            name = source["name"]
            sanitized_name = sanitize_name(name)
            if sanitized_name in name_to_metric:
                print(f"{sanitized_name}: {name_to_metric[sanitized_name]}")
        print(f"mean: {mean}")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import re

def main():
    if len(sys.argv) < 2:
        sys.exit(1)

    xml_path = sys.argv[1]
    overrides = sys.argv[2:]

    # Validate and sanitize overrides
    valid_chars = r'^[a-zA-Z0-9_][a-zA-Z0-9._-]*$'
    config_dict = {}

    # Parse XML file
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML file: {e}")
    except FileNotFoundError:
        sys.exit(f"File not found: {xml_path}")

    # Build initial dictionary from XML entries
    for entry in root:
        if entry.tag == 'entry':
            name = entry.get('name')
            value = entry.get('value')
            if name and value:
                # Validate name and value for safety
                if re.match(valid_chars, name):
                    config_dict[name] = value

    # Apply command-line overrides with validation
    for override in overrides:
        if '=' not in override:
            sys.exit(f"Invalid override format: {override}. Must be 'name=value'.")

        name, value = override.split('=', 1)

        # Validate name and value
        if not name or not re.match(valid_chars, name):
            sys.exit(f"Invalid name in override: {name}. Names must contain only alphanumeric, underscore, dot, and hyphen, and start with alphanumeric.")

        # Validate value - ensure it doesn't contain dangerous sequences
        # This is a basic check to prevent shell injection or path traversal
        # More sophisticated checks can be added based on use case
        if re.search(r'[\x00-\x1F\x7F]|;|&|\$|\`|`|\'|\"|\\|\x00', value):
            sys.exit(f"Invalid value in override: {value}. Contains potentially dangerous characters.")

        config_dict[name] = value

    # Print the result as JSON
    print(json.dumps(config_dict, indent=2))

if __name__ == "__main__":
    main()

import sys
