    try:
        root = ET.fromstring(xml_content)
    except ET.ParseError as e:
        print(f"Error: Invalid XML format - {e}")
        sys.exit(1)

    for check_elem in root.findall('check'):
        name = check_elem.get('name')
        url = check_elem.get('url')

        if not name or not url:
            print("Error: Missing 'name' or 'url' attribute in <check> element")
            sys.exit(1)

        # Validate URL format to prevent open redirects and path traversal
        try:
            parsed_url = urllib.parse.urlparse(url)
            if not all([parsed_url.scheme, parsed_url.netloc]):
                print(f"Error: Invalid URL format - {url}")
                sys.exit(1)

            # Check for suspicious patterns in URL (basic heuristic)
            if any(pattern in url for pattern in ['..', ';', '|', '&&', '||', 'sleep', 'exec', 'system']):
                print(f"Error: Suspicious URL pattern detected in {url}")
                sys.exit(1)

            response = requests.get(url, timeout=10)
            status_code = response.status_code
            print(f"CHECK {name} {status_code}")

            on_fail_elem = check_elem.find('on_fail')
            if on_fail_elem is not None and status_code != 200:
                cmd = on_fail_elem.text.strip() if on_fail_elem.text else ""
                if cmd:
                    # Validate command for dangerous patterns
                    if any(pattern in cmd for pattern in [';', '|', '&', '&&', '||', 'sleep', 'exec', 'system', 'rm', 'del', 'chmod', 'sudo']):
                        print(f"Error: Command contains dangerous pattern: {cmd}")
                        print(f"CMD {name} 1")
                    else:
                        # Execute command safely using a shell-safe approach
                        try:
                            # Split command into arguments to avoid shell injection
                            args = cmd.split()
                            # Use subprocess with shell=False and explicit arguments
                            result = subprocess.run(args, capture_output=True, text=True, check=False)
                            print(f"CMD {name} {result.returncode}")
                        except Exception as e:
                            print(f"CMD {name} 1")
        except requests.exceptions.RequestException as e:
            print(f"CHECK {name} 0")
            on_fail_elem = check_elem.find('on_fail')
            if on_fail_elem is not None:
                cmd = on_fail_elem.text.strip() if on_fail_elem.text else ""
                if cmd:
