import sys
import json
import requests
from xml.etree import ElementTree as ET
from urllib.parse import urlparse, urljoin
from typing import Dict, List, Optional
import urllib3

# Disable insecure warnings for SSL (if needed) and set a reasonable timeout
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def parse_config(xml_path: str) -> List[Dict[str, str]]:
    """Parse the XML configuration file safely."""
    try:
        with open(xml_path, 'r', encoding='utf-8') as file:
            content = file.read()
    except FileNotFoundError:
        sys.exit(f"Configuration file {xml_path} not found.")
    except PermissionError:
        sys.exit(f"Permission denied when reading configuration file {xml_path}.")

    try:
        root = ET.fromstring(content)
    except ET.ParseError as e:
        sys.exit(f"Error parsing XML configuration: {e}")

    feeds = []
    for feed_elem in root.findall('feed'):
        url = feed_elem.get('url')
        name = feed_elem.get('name')

        if not url:
            sys.exit("Missing 'url' attribute in feed element.")

        # Validate URL format using a basic scheme and domain check
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            sys.exit(f"Invalid URL format: {url}")

        # Validate that the URL does not contain potentially dangerous paths or parameters
        # This is a basic check; in production, use a more robust URL validation library
        if '..' in parsed_url.path or '//' in parsed_url.path or ' ' in parsed_url.path:
            sys.exit(f"URL contains unsafe path components: {url}")

        if not name:
            name = url

        feeds.append({'url': url, 'name': name})

    return feeds

def is_valid_rss_content(content: bytes) -> bool:
    """Check if the content is likely to be valid RSS XML."""
    if not content or len(content) == 0:
        return False

    # Check for basic RSS XML structure (presence of RSS or channel)
    try:
        root = ET.fromstring(content)
        # Check for common RSS elements
        if root.tag in ['rss', 'channel']:
            return True
    except ET.ParseError:
        pass

    return False

def fetch_feed_titles(feeds: List[Dict[str, str]]) -> Dict[str, List[str]]:
    """Fetch titles from RSS feeds with security mitigations."""
    result: Dict[str, List[str]] = {}

    # Use a single-threaded approach to avoid overwhelming servers
    for feed in feeds:
        url = feed['url']
        name = feed['name']

        try:
            # Set a reasonable timeout to prevent hanging
            response = requests.get(url, timeout=10, verify=True, allow_redirects=False)

            # Check if the response is a redirect or has a non-200 status
            if response.status_code != 200:
                result[name] = []
                continue

            # Check if the response content is valid RSS XML
            content = response.content
            if not is_valid_rss_content(content):
                result[name] = []
                continue

            # Parse the XML with security settings
            try:
                root = ET.fromstring(content)
                titles = []
                # Use a safe XPath to find items and titles
                for item in root.findall('.//item'):
                    title_elem = item.find('title')
                    if title_elem is not None and title_elem.text:
                        titles.append(title_elem.text.strip())
                result[name] = titles
            except ET.ParseError:
                # If parsing fails, return empty list
                result[name] = []

        except requests.RequestException as e:
            # Log or handle request exceptions (e.g., timeout, connection error)
            result[name] = []

    return result

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: python fetch_feed_titles.py path/to/config.xml")

    config_path = sys.argv[1]
    feeds = parse_config(config_path)
    titles_data = fetch_feed_titles(feeds)
    print(json.dumps(titles_data, indent=2))

if __name__ == "__main__":
    main()

import sys
import json
import requests
import os
from urllib.parse import urlparse, urljoin

def main(config_path):
    # Read and decode configuration
    try:
        with open(config_path, 'r', encoding='utf-8') as f:
            config = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print("Error reading configuration file.", file=sys.stderr)
        sys.exit(1)

    api_url = config.get("api_url")
    page_title = config.get("page_title")

    if not api_url or not page_title:
        print("Missing required configuration keys.", file=sys.stderr)
        sys.exit(1)

    # Validate and sanitize page_title to prevent HTML injection
    if not isinstance(page_title, str):
        page_title = ""
    # Remove any potentially dangerous characters or tags
    safe_page_title = page_title.strip()
    # Ensure only safe characters are used (no script, style, etc.)
    safe_page_title = safe_page_title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')

    # Validate and sanitize api_url to prevent open redirects and SSRF
    parsed_url = urlparse(api_url)
    if not parsed_url.scheme or not parsed_url.netloc:
        print("Invalid API URL format.", file=sys.stderr)
        sys.exit(1)

    # Ensure the API URL is from a trusted domain (basic check)
    # This is a simplified check; in production, use a whitelist of allowed domains
    allowed_domains = ["example.com"]  # This should be configured securely
    if parsed_url.netloc.lower() not in [domain.lower() for domain in allowed_domains]:
        print("API URL from unauthorized domain.", file=sys.stderr)
        sys.exit(1)

    # Fetch articles from API or use cache
    cache_file = "news_cache.json"
    articles = []

    # Try to fetch from API
    try:
        response = requests.get(api_url, timeout=10)
        response.raise_for_status()
        data = response.json()

        # Validate data structure
        if isinstance(data, list):
            # Filter and sanitize each article
            sanitized_articles = []
            for item in data:
                if isinstance(item, dict):
                    title = item.get("title", "").strip()
                    url = item.get("url", "").strip()
                    # Sanitize title and url
                    if title and url:
                        # Remove dangerous HTML tags from title
                        title = title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')
                        # Validate URL format
                        if is_safe_url(url):
                            sanitized_articles.append({
                                "title": title,
                                "url": url
                            })
            articles = sanitized_articles
        else:
            print("API returned invalid data format.", file=sys.stderr)
    except (requests.RequestException, json.JSONDecodeError) as e:
        # If API request fails, try to load from cache
        pass

    # If API failed, try to load from cache
    if not articles:
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                cache_data = json.load(f)
            if isinstance(cache_data, list):
                # Filter and sanitize cached articles
                sanitized_articles = []
                for item in cache_data:
                    if isinstance(item, dict):
                        title = item.get("title", "").strip()
                        url = item.get("url", "").strip()
                        if title and url:
                            title = title.replace('<', '&lt;').replace('>', '&gt;').replace('&', '&amp;')
                            if is_safe_url(url):
                                sanitized_articles.append({
                                    "title": title,
                                    "url": url
                                })
                articles = sanitized_articles
        except (FileNotFoundError, json.JSONDecodeError):
            # Cache file missing or invalid, use empty list
            pass

    # Write articles to cache if we have them
    if articles:
        try:
            with open(cache_file, 'w', encoding='utf-8') as f:
                json.dump(articles, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"Error writing cache file: {e}", file=sys.stderr)

    # Generate HTML output with safe sanitization
    html = [
        "<!DOCTYPE html>",
        "<html>",
        "  <head>",
        f"    <title>{safe_page_title}</title>",
        "  </head>",
        "  <body>",
        f"    <h1>{safe_page_title}</h1>",
        "    <ul>"
    ]

    for article in articles:
        title = article.get("title", "")
        url = article.get("url", "")
        if title and url:
            # Ensure URL is safe and properly formatted
            html.append(f"      <li><a href='{url}' target='_blank'>{title}</a></li>")

    html.append("    </ul>")
    html.append("  </body>")
    html.append("</html>")

    print("\n".join(html))

def is_safe_url(url):
    """Check if URL is safe by validating against known dangerous patterns."""
    # Check for common XSS vectors
    dangerous_patterns = [
        'javascript:', 'vbscript:', 'data:', 'about:', 'mailto:',
        'exec', 'eval', 'document.write', 'window.open', 'onload'
    ]

    for pattern in dangerous_patterns:
        if pattern in url.lower():
            return False

    # Validate basic URL structure
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except Exception:
        return False

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python news_page.py CONFIG_PATH", file=sys.stderr)
        sys.exit(1)
    main(sys.argv[1])

import sys
import json
import os
from typing import List, Dict, Any
import ast

def fetch_and_cache_records(data_url: str, use_cache: bool) -> List[Dict[str, Any]]:
    cache_file = '.remote_eval_cache'

    if use_cache and os.path.exists(cache_file):
        try:
            with open(cache_file, 'r', encoding='utf-8') as f:
                records = json.load(f)
                return records
        except (json.JSONDecodeError, IOError) as e:
            # If cache is corrupted or inaccessible, fall back to fetching
            pass

    # Fetch from URL
    try:
        import requests
        response = requests.get(data_url, timeout=10)
        response.raise_for_status()
        body = response.text
    except requests.RequestException as e:
        print(f"Error fetching data from {data_url}: {e}", file=sys.stderr)
        sys.exit(1)

    # Parse newline-delimited JSON
    records = []
    for line in body.strip().split('\n'):
        line = line.strip()
        if line:
            try:
                record = json.loads(line)
                # Validate required fields
                if not all(k in record for k in ["id", "expression", "x"]):
                    print(f"Error: Missing required field(s) in record: {record}", file=sys.stderr)
                    continue
                # Validate types
                if not isinstance(record["id"], str):
                    print(f"Error: 'id' must be a string", file=sys.stderr)
                    continue
                if not isinstance(record["expression"], str):
                    print(f"Error: 'expression' must be a string", file=sys.stderr)
                    continue
                if not isinstance(record["x"], (int, float)):
                    print(f"Error: 'x' must be a number", file=sys.stderr)
                    continue
                records.append(record)
            except json.JSONDecodeError as e:
                print(f"Error parsing JSON line: {e}", file=sys.stderr)
                continue

    # Cache the records if not using cache
    if not use_cache:
        try:
            with open(cache_file, 'w', encoding='utf-8') as f:
                json.dump(records, f, ensure_ascii=False, indent=None)
        except IOError as e:
            print(f"Error writing to cache file: {e}", file=sys.stderr)
            sys.exit(1)

    return records

def evaluate_records(records: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results = []
    for record in records:
        try:
            x = record["x"]
            expression = record["expression"]

            # Validate expression syntax using AST
            tree = ast.parse(expression, mode='eval')

            # Check for dangerous operations
            for node in ast.walk(tree):
                if isinstance(node, (ast.Call, ast.Name, ast.Attribute)):
                    # Check for dangerous functions
                    if isinstance(node, ast.Call):
                        func_name = node.func.id if isinstance(node.func, ast.Name) else None
                        if func_name in ['os', 'subprocess', 'eval', 'exec', 'open', 'import']:
                            raise ValueError(f"Expression contains dangerous function: {func_name}")
                    elif isinstance(node, ast.Attribute):
                        attr_name = node.attr
                        if attr_name in ['system', 'popen', 'exec', 'read', 'write']:
                            raise ValueError(f"Expression contains dangerous attribute: {attr_name}")

            # Safe evaluation using ast.literal_eval-like logic
            # We only allow basic arithmetic and expressions with x
            # We validate the AST structure to ensure it's safe
            # We use eval with a restricted namespace
            safe_namespace = {"x": x}
            result = eval(expression, safe_namespace, {})

            # Create output record
            output_record = {
                "id": record["id"],
                "expression": record["expression"],
                "x": record["x"],
                "result": result
            }
            results.append(output_record)

        except (SyntaxError, ValueError, Exception) as e:
            print(f"Error evaluating expression: {e}", file=sys.stderr)
            # If evaluation fails, create a record with result as None
            output_record = {
                "id": record["id"],
                "expression": record["expression"],
                "x": record["x"],
                "result": None
            }
            results.append(output_record)

    return results

def main():
    if len(sys.argv) < 2:
        print("Usage: python remote_eval.py <DATA_URL> [--use-cache]", file=sys.stderr)
        sys.exit(1)

    data_url = sys.argv[1]
    use_cache = '--use-cache' in sys.argv

    records = fetch_and_cache_records(data_url, use_cache)

    output_records = evaluate_records(records)

    # Output each record as newline-delimited JSON
    for record in output_records:
        print(json.dumps(record, ensure_ascii=False))

if __name__ == '__main__':
    main()

import sys
import xml.etree.ElementTree as ET
import os
import requests
from urllib.parse import urljoin, urlparse

def load_config():
    try:
        tree = ET.parse('services.xml')
        root = tree.getroot()
        services = {}
        for service in root.findall('service'):
            name = service.get('name')
            base_url = service.get('base_url')
            token_env = service.get('token_env')
            if name and base_url and token_env:
                # Validate base_url format: must have a scheme and netloc
                parsed = urlparse(base_url)
                if not parsed.scheme or not parsed.netloc:
                    continue
                services[name] = {
                    'base_url': base_url,
                    'token_env': token_env
                }
        return services
    except FileNotFoundError:
        return {}
    except Exception as e:
        # Log error but don't exit, return empty dict
        return {}

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    service_name = sys.argv[1]
    path = sys.argv[2]

    services = load_config()
    if service_name not in services:
        print(f"Unknown service: {service_name}")
        sys.exit(1)

    service = services[service_name]
    token_env = service['token_env']
    token = os.getenv(token_env)

    if not token or token == "":
        print(f"Missing token for service: {service_name}")
        sys.exit(1)

    base_url = service['base_url']

    # Validate and sanitize the path to prevent path traversal
    # Only allow absolute paths or paths that start with a forward slash
    if not path.startswith('/'):
        print(f"Invalid path: {path}")
        sys.exit(1)

    # Use urljoin to safely combine base_url and path, preventing path traversal
    final_url = urljoin(base_url, path)

    try:
        response = requests.get(final_url, headers={'Authorization': f'Bearer {token}'}, timeout=10)
        print(f"URL: {final_url}")
        print(f"Status: {response.status_code}")
        if response.content:
            try:
                body = response.text
                print(body)
            except UnicodeDecodeError:
                # Fallback to latin1 encoding with replacement for non-text content
                print(response.content.decode('latin1', errors='replace'))
        else:
            print("")
    except requests.exceptions.RequestException as e:
        # Log the error but do not expose detailed information
        print(f"URL: {final_url}")
        print(f"Status: 500")
        print("Error occurred during request")

if __name__ == "__main__":
    main()

import sys
import time
import json
import os
import requests

def fetch_users():
    token = os.getenv('SERVICE_ACCESS_TOKEN')
    if not token or not token.strip():
        print("SERVICE_ACCESS_TOKEN not set", file=sys.stderr)
        sys.exit(1)

    user_ids = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            # Validate user ID: must be non-empty, contain only alphanumeric and underscore, and not contain path traversal patterns
            if not line.isalnum() and not any(c.isalnum() or c in '_-' for c in line):
                print(f"INVALID USER ID: {line}", file=sys.stderr)
                continue
            if '..' in line or '/' in line or '\\\\' in line or '\\/' in line:
                print(f"INVALID USER ID: {line}", file=sys.stderr)
                continue
            user_ids.append(line)

    if not user_ids:
        sys.exit(0)

    # Throttle: at most 2 requests per second (0.5 seconds between requests)
    last_request_time = 0
    results = []
    errors = []

    for user_id in user_ids:
        # Wait until it's time to make the next request
        current_time = time.time()
        if current_time - last_request_time < 0.5:
            sleep_duration = 0.5 - (current_time - last_request_time)
            time.sleep(sleep_duration)

        url = f"https://example.com/api/users/{user_id}"
        headers = {
            "Authorization": f"Bearer {token}"
        }

        try:
            response = requests.get(url, headers=headers, timeout=5)
            if response.status_code // 100 == 2:  # 2xx status code
                try:
                    data = response.json()
                    # Validate required fields exist and are strings
                    if not isinstance(data, dict):
                        errors.append(user_id)
                        continue
                    if 'id' not in data or 'name' not in data or 'email' not in data:
                        errors.append(user_id)
                        continue
                    if not isinstance(data['id'], str) or not isinstance(data['name'], str) or not isinstance(data['email'], str):
                        errors.append(user_id)
                        continue
                    results.append((data['id'], data['name'], data['email']))
                except json.JSONDecodeError:
                    errors.append(user_id)
            else:
                errors.append(user_id)
        except requests.exceptions.RequestException as e:
            errors.append(user_id)

        last_request_time = time.time()

    # Output successful results in the same order as input
    for result in results:
        print(f"{result[0]}\t{result[1]}\t{result[2]}")

    # Output failed user IDs to stderr
    for error in errors:
        print(f"FAILED {error}", file=sys.stderr)

    # Exit with 0 if at least one request was attempted
    sys.exit(0)

