import sys
import requests
import xml.etree.ElementTree as ET
import json
from urllib.parse import urlparse, parse_qs
import re

def is_valid_url(url):
    """Validate URL format to prevent open redirects and malicious content."""
    if not url or not isinstance(url, str):
        return False

    # Basic schema validation
    parsed = urlparse(url)
    if not parsed.scheme or not parsed.netloc:
        return False

    # Prevent protocol spoofing (e.g., javascript:, data:, etc.)
    if parsed.scheme in ['javascript', 'data', 'mailto', 'tel', 'news', 'ftp']:
        return False

    # Prevent open redirects by checking for suspicious query parameters
    # This is a simplified check; in production, more robust validation is needed
    query_params = parse_qs(parsed.query)
    # Check for common redirect patterns (e.g., redirect, to, go, url)
    redirect_keywords = ['redirect', 'to', 'go', 'url', 'next', 'target']
    for kw in redirect_keywords:
        if kw in query_params:
            return False

    # Prevent malformed or suspicious characters
    # Allow only standard URL characters
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', url):
        return False

    return True

def parse_xml_safely(xml_content):
    """Parse XML content safely by disabling external entity processing."""
    try:
        # Parse XML with disabled external entities
        parser = ET.XMLParser(encoding='utf-8', resolve_entities=False)
        root = ET.fromstring(xml_content, parser=parser)
        return root
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML content: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]

    try:
        with open(config_path, 'r', encoding='utf-8') as file:
            xml_content = file.read()
    except FileNotFoundError:
        sys.exit(1)

    try:
        root = parse_xml_safely(xml_content)
    except ValueError as e:
        sys.exit(1)

    endpoints = {}
    for endpoint_elem in root.findall('endpoint'):
        name = endpoint_elem.get('name')
        url = endpoint_elem.get('url')

        if not name or not url:
            continue

        # Validate URL before making request
        if not is_valid_url(url):
            # Log warning or skip, but still include in output with null status and empty body
            endpoints[name] = {
                "url": url,
                "status": None,
                "body": ""
            }
            continue

        endpoints[name] = {
            "url": url,
            "status": None,
            "body": ""
        }

        try:
            response = requests.get(url, timeout=10)
            endpoints[name]["status"] = response.status_code
            body = response.text
            if len(body) > 200:
                body = body[:200]
            endpoints[name]["body"] = body
        except requests.RequestException:
            # Request failed, status remains None, body is empty string
            pass

    print(json.dumps(endpoints, indent=2))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import time
import requests
from urllib.parse import urlparse, urljoin
import re

def load_config(config_path):
    try:
        tree = ET.parse(config_path)
        root = tree.getroot()

        # Validate root element and required children
        if root.tag != 'config':
            raise ValueError("Root element must be 'config'")

        limits_elem = root.find('limits')
        if limits_elem is None:
            raise ValueError("Missing 'limits' element in config")

        min_interval_str = limits_elem.get('min_interval_seconds')
        if min_interval_str is None:
            raise ValueError("min_interval_seconds attribute missing in limits")

        try:
            min_interval = float(min_interval_str)
            if min_interval < 0:
                raise ValueError("min_interval_seconds must be non-negative")
        except ValueError as e:
            raise ValueError(f"Invalid min_interval_seconds value: {min_interval_str}") from e

        services = {}
        services_elem = root.find('services')
        if services_elem is None:
            raise ValueError("Missing 'services' element in config")

        for service_elem in services_elem.findall('service'):
            name = service_elem.get('name')
            base_url = service_elem.get('base_url')

            if not name or not base_url:
                continue

            # Validate service name and base URL
            if not re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', name):
                raise ValueError(f"Invalid service name: {name}")

            # Validate base URL format
            parsed = urlparse(base_url)
            if not parsed.scheme or not parsed.netloc:
                raise ValueError(f"Invalid base URL format: {base_url}")

            # Ensure it's a secure protocol (HTTPS only)
            if parsed.scheme not in ('https', 'http'):
                raise ValueError(f"Base URL must use HTTPS or HTTP: {base_url}")

            # Prevent internal or local access
            if parsed.netloc.lower() in ('localhost', '127.0.0.1', '0.0.0.0'):
                raise ValueError(f"Base URL cannot be internal: {base_url}")

            services[name] = base_url

        return min_interval, services

    except ET.ParseError as e:
        raise ValueError(f"Invalid XML format in configuration file: {e}")
    except Exception as e:
        raise ValueError(f"Error loading configuration: {e}")

def is_valid_item_id(item_id):
    """Validate item_id to prevent path traversal and excessive length"""
    if not item_id:
        return False
    # Limit length to prevent resource exhaustion
    if len(item_id) > 1024:
        return False
    # Prevent path traversal attempts
    if '..' in item_id or '/' in item_id or '\\' in item_id:
        return False
    # Prevent malicious characters
    if not re.match(r'^[a-zA-Z0-9._-]+$', item_id):
        return False
    return True

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <config_file.xml>", file=sys.stderr)
        sys.exit(1)

    config_path = sys.argv[1]
    try:
        min_interval, services = load_config(config_path)
    except ValueError as e:
        print(f"Configuration error: {e}", file=sys.stderr)
        sys.exit(1)

    total_requests = 0
    total_bytes = 0

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 2:
            continue

        service_name, item_id = parts[0], parts[1]

        # Validate service name
        if service_name not in services:
            continue

        # Validate item_id
        if not is_valid_item_id(item_id):
            continue

        base_url = services[service_name]
        # Construct URL safely using urljoin to prevent path traversal
        request_url = urljoin(base_url, f"?item={item_id}")

        # Enforce rate limit after first request
        if total_requests > 0:
            time.sleep(min_interval)

        try:
            response = requests.get(request_url, timeout=10)
            status_code = response.status_code
            body_length = len(response.content)

            print(f"{service_name}\t{item_id}\t{status_code}\t{body_length}")

            total_requests += 1
            total_bytes += body_length

        except requests.exceptions.RequestException as e:
            # Log error without exposing details
            print(f"{service_name}\t{item_id}\t500\t0")
            total_requests += 1

    print(f"SUMMARY total_requests={total_requests} total_bytes={total_bytes}")

if __name__ == "__main__":
    main()

