    used_cost = 0

    for job in jobs:
        job_id = job['id']
        cost = job['cost']
        expr = job['expr']

        if used_cost + cost > memory_budget:
            print(f"SKIPPED {job_id}")
            continue

        if job_id in cache:
            result = cache[job_id]
        else:
            result = evaluate_expression(expr, n)
            cache[job_id] = result

        used_cost += cost
        print(f"RESULT {job_id} {result}")

    save_cache(cache)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python job_runner.py path/to/config.json")
        sys.exit(1)
    main(sys.argv[1])

