import sys
import xml.etree.ElementTree as ET
import hashlib

def compute_digest(secret, token):
    return hashlib.sha256((secret + token).encode()).hexdigest().upper()

def main():
    if len(sys.argv) != 4:
        print("Usage: python auth_check.py CONFIG_PATH USERNAME ACTION")
        sys.exit(1)

    config_path, username, action = sys.argv[1:]

    try:
        tree = ET.parse(config_path)
        root = tree.getroot()
    except ET.ParseError:
        print("DENIED")
        sys.exit(1)

    secret = root.find('secret').get('key')
    user = root.find(f"./user[@name='{username}']")

    if user is None:
        print("DENIED")
        sys.exit(1)

    token = input().strip()
    expected_digest = user.get('tokenDigest')

    if compute_digest(secret, token) != expected_digest:
        print("DENIED")
        sys.exit(1)

    roles = user.get('roles', '').split(',')
    allowed_actions = {
        'reader': {'read'},
        'writer': {'read', 'write'},
        'admin': {'read', 'write', 'delete'}
    }

    if any(action in allowed_actions.get(role, set()) for role in roles):
        print("ALLOWED")
    else:
        print("DENIED")

