import sys
import os
import json
import hmac
import hashlib
import urllib.request
import urllib.error
from urllib.parse import urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def main():
    if len(sys.argv) != 3:
        print("INVALID LICENSE")
        return

    license_key, license_server_url = sys.argv[1], sys.argv[2]
    shared_secret = os.getenv('LICENSE_SHARED_SECRET')

    if not shared_secret:
        print("INVALID LICENSE")
        return

    if not is_valid_url(license_server_url):
        print("INVALID LICENSE")
        return

    try:
        request_data = json.dumps({"license_key": license_key}).encode('utf-8')
        request = urllib.request.Request(license_server_url, data=request_data, method='POST')
        with urllib.request.urlopen(request) as response:
            license_info = json.loads(response.read().decode('utf-8'))

        required_fields = {"user", "plan", "expires", "signature"}
        if not all(field in license_info for field in required_fields):
            print("INVALID LICENSE")
            return

        message = f"user={license_info['user']};plan={license_info['plan']};expires={license_info['expires']}"
        expected_signature = hmac.new(
            shared_secret.encode('utf-8'),
            message.encode('utf-8'),
            hashlib.sha256
        ).hexdigest()

        if hmac.compare_digest(expected_signature, license_info['signature']):
            print(f"User: {license_info['user']}, Plan: {license_info['plan']}, Expires: {license_info['expires']}")
        else:
            print("INVALID LICENSE")

    except (urllib.error.URLError, json.JSONDecodeError, ValueError):
        print("INVALID LICENSE")

if __name__ == "__main__":
    main()

