        if not re.match(r'^[a-zA-Z0-9-]+$', username):
            print("ERROR: Invalid username format", file=sys.stderr)
            sys.exit(1)

        with urllib.request.urlopen(f"https://api.github.com/users/{username}") as response:
            if response.status != 200:
                print(f"ERROR: Failed to fetch user data", file=sys.stderr)
                sys.exit(1)
            user_data = json.loads(response.read().decode())

        with urllib.request.urlopen(f"https://api.github.com/users/{username}/repos") as response:
            if response.status != 200:
                print(f"ERROR: Failed to fetch repositories data", file=sys.stderr)
                sys.exit(1)
